    return labToRgb(vec3(
      sampleInvCdf(0.0, gaussianCdf(lab.x, 50.0, 20.0)),
      sampleInvCdf(1.0, gaussianCdf(lab.y, 0.0, 10.0)),
      sampleInvCdf(2.0, gaussianCdf(lab.z, 0.0, 10.0))));
